/* ReclaimMyTime architecture map.
 *
 * Renders design/architecture/architecture.json (generated by server/scripts/arch_extract.py)
 * with the curated design/architecture/overlay.json. Hand-drawn SVG; positions are a pure
 * function of overlay layer rows and package order, so the picture only moves when the overlay
 * or the package set changes. Loaded by index.html through @babel/standalone (no build step).
 */

const { useMemo, useState, useCallback } = React;

const KINDS = {
  import: { label: "Python import", dash: null, width: 1.4, offset: 14 },
  reference: { label: "Swift reference (inferred)", dash: "5 4", width: 1.3, offset: 14 },
  http: { label: "HTTP (iOS → API route)", dash: "10 4 2 4", width: 2, offset: 46 },
  forbidden: { label: "import-linter: must not depend", dash: "3 4", width: 1.6, offset: 30 },
};

// Viewbox units are close to CSS pixels at typical widths (the map column is ~900-1000px on a
// 1440px window), so font sizes below are roughly what the reader sees.
const REGIONS = {
  server: { x: 0, w: 410, cols: 2, title: "Server", sub: "server/app (Python)" },
  ios: { x: 440, w: 560, cols: 3, title: "iOS", sub: "ios/ReclaimMyTime (Swift)" },
};
const DIVIDER_X = 425;
const VIEW_W = 1000;
const NODE_H = 52;
const SUBROW_H = NODE_H + 16;
const ROW_LABEL_H = 26;
const ROW_GAP = 12;
const TOP = 58;

// ------------------------------------------------------------------------------------------
// layout

function computeLayout(packages, overlay) {
  const layers = overlay.layers || [];
  const ovp = overlay.packages || {};
  const pos = {};
  const bands = [];
  let maxY = 0;
  for (const side of ["server", "ios"]) {
    const region = REGIONS[side];
    const rows = new Map();
    for (const p of packages.filter((q) => q.side === side)) {
      const ov = ovp[p.id];
      const layer = ov && layers.find((l) => l.id === ov.layer && l.side === side);
      const row = layer ? layer.row : 999;
      if (!rows.has(row)) rows.set(row, { labels: [], items: [] });
      const r = rows.get(row);
      const label = layer ? layer.label : "Unassigned (missing from overlay.json)";
      if (!r.labels.includes(label)) r.labels.push(label);
      r.items.push({ p, order: ov && ov.order != null ? ov.order : 999, layer });
    }
    let y = TOP;
    const slotW = region.w / region.cols;
    for (const row of [...rows.keys()].sort((a, b) => a - b)) {
      const r = rows.get(row);
      r.items.sort((a, b) => a.order - b.order || a.p.id.localeCompare(b.p.id));
      const chunks = [];
      for (let i = 0; i < r.items.length; i += region.cols) {
        chunks.push(r.items.slice(i, i + region.cols));
      }
      const h = ROW_LABEL_H + chunks.length * SUBROW_H;
      const labels = [];
      chunks.forEach((chunk, ci) => {
        const startX = region.x + (region.w - chunk.length * slotW) / 2;
        chunk.forEach((it, i) => {
          const n = {
            x: startX + slotW * i + slotW / 2,
            y: y + ROW_LABEL_H + ci * SUBROW_H + NODE_H / 2 + 2,
            w: slotW - 18,
            h: NODE_H,
            color: it.layer ? it.layer.color : "#999",
          };
          pos[it.p.id] = n;
          // one label per layer, left-aligned over the first node of that layer in the row
          const label = it.layer ? it.layer.label : "Unassigned (missing from overlay.json)";
          if (ci === 0 && !labels.some((l) => l.text === label)) {
            const solo = r.labels.length === 1;
            labels.push({ text: label, x: solo ? region.x + 12 : n.x - n.w / 2 + 2 });
          }
        });
      });
      bands.push({ side, x: region.x, y, w: region.w, h, labels });
      y += h + ROW_GAP;
    }
    maxY = Math.max(maxY, y);
  }
  return { pos, bands, height: maxY + 8 };
}

function trim(n, ux, uy) {
  const tx = ux ? n.w / 2 / Math.abs(ux) : Infinity;
  const ty = uy ? n.h / 2 / Math.abs(uy) : Infinity;
  return Math.min(tx, ty);
}

function edgeGeometry(a, b, kind) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  const s = { x: a.x + ux * trim(a, ux, uy), y: a.y + uy * trim(a, ux, uy) };
  const e = { x: b.x - ux * (trim(b, ux, uy) + 3), y: b.y - uy * (trim(b, ux, uy) + 3) };
  const off = KINDS[kind].offset + Math.min(len * 0.05, 36);
  const c = { x: (s.x + e.x) / 2 - uy * off, y: (s.y + e.y) / 2 + ux * off };
  const r = (v) => Math.round(v * 10) / 10;
  return `M${r(s.x)},${r(s.y)} Q${r(c.x)},${r(c.y)} ${r(e.x)},${r(e.y)}`;
}

// ------------------------------------------------------------------------------------------
// symbol helpers

function countSymbols(files) {
  let n = 0;
  const walk = (t) => {
    n += 1 + (t.methods || []).length + (t.variables || []).length;
    (t.types || []).forEach(walk);
  };
  for (const f of files) {
    (f.types || []).forEach(walk);
    n += (f.functions || []).length + (f.variables || []).length;
  }
  return n;
}

const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;

function partialText(e) {
  const ends = e.partial_ends || [];
  const which = ends.length === 2 ? "source and target" : ends[0] || "one";
  return `some modules at the ${which} end${ends.length === 2 ? "s" : ""}`;
}

const has = (name, q) => name.toLowerCase().includes(q);

function filterType(t, q) {
  if (!q || has(t.name, q)) return t;
  const methods = (t.methods || []).filter((m) => has(m.name, q));
  const variables = (t.variables || []).filter((v) => has(v.name, q));
  const types = (t.types || []).map((n) => filterType(n, q)).filter(Boolean);
  if (!methods.length && !variables.length && !types.length) return null;
  return { ...t, methods, variables, types };
}

function filterFile(f, q) {
  if (!q) return f;
  const types = (f.types || []).map((t) => filterType(t, q)).filter(Boolean);
  const functions = (f.functions || []).filter((fn) => has(fn.name, q));
  const variables = (f.variables || []).filter((v) => has(v.name, q));
  if (!types.length && !functions.length && !variables.length) return null;
  return { ...f, types, functions, variables };
}

function Highlight({ text, q }) {
  if (!q) return text;
  const i = text.toLowerCase().indexOf(q);
  if (i < 0) return text;
  return (
    <>
      {text.slice(0, i)}
      <mark>{text.slice(i, i + q.length)}</mark>
      {text.slice(i + q.length)}
    </>
  );
}

// ------------------------------------------------------------------------------------------
// symbol rendering

function Badges({ item }) {
  const b = [];
  if (item.access && item.access !== "internal") b.push(item.access);
  if (item.setter_access) b.push(`${item.setter_access}(set)`);
  if (item.static) b.push("static");
  if (item.async) b.push("async");
  if (item.requirement) b.push("requirement");
  if (item.storage && item.storage !== "stored") b.push(item.storage);
  if (item.lazy) b.push("lazy");
  if (item.constBadge) b.push("const");
  if (item.final) b.push("final");
  return b.map((x) => (
    <span key={x} className="badge">
      {x}
    </span>
  ));
}

function Decorators({ list }) {
  if (!list || !list.length) return null;
  return <div className="decorators">{list.join(" ")}</div>;
}

function FunctionRow({ fn, q }) {
  return (
    <li className="sym fn">
      <Decorators list={fn.decorators} />
      <code className="sig">
        <Highlight text={fn.signature} q={q} />
      </code>{" "}
      <Badges item={fn} /> <span className="line">:{fn.line}</span>
      {fn.doc && <div className="doc">{fn.doc}</div>}
    </li>
  );
}

function VariableRow({ v, q, swift }) {
  const kw = swift ? (v.constant ? "let " : "var ") : "";
  return (
    <li className="sym var">
      <Decorators list={v.attributes} />
      <code className="sig">
        {kw}
        <Highlight text={v.name} q={q} />
        {v.type ? `: ${v.type}` : ""}
        {v.value !== undefined ? ` = ${v.value}` : ""}
      </code>{" "}
      <Badges item={{ ...v, constBadge: !swift && v.constant }} />{" "}
      <span className="line">:{v.line}</span>
    </li>
  );
}

function TypeBlock({ t, q, swift, depth, expanded, toggle, keyPrefix }) {
  const key = `${keyPrefix}/${t.name}:${t.line}`;
  const open = q ? true : expanded.has(key);
  const members = (t.methods || []).length + (t.variables || []).length + (t.types || []).length;
  return (
    <li className={`sym type depth-${Math.min(depth, 3)}`}>
      <Decorators list={t.decorators || t.attributes} />
      <button type="button" className="disclosure" onClick={() => toggle(key)} aria-expanded={open}>
        <span className="chev">{members ? (open ? "▾" : "▸") : "·"}</span>
        <span className="kw">{t.kind}</span>{" "}
        <strong>
          <Highlight text={t.name} q={q} />
        </strong>
        {t.bases && t.bases.length ? <span className="bases">: {t.bases.join(", ")}</span> : null}
        {t.aliases ? <span className="bases"> = {t.aliases}</span> : null}
      </button>{" "}
      <Badges item={t} /> <span className="line">:{t.line}</span>
      {t.doc && <div className="doc">{t.doc}</div>}
      {open && members > 0 && (
        <ul className="members">
          {(t.variables || []).map((v) => (
            <VariableRow key={`v${v.name}${v.line}`} v={v} q={q} swift={swift} />
          ))}
          {(t.methods || []).map((m) => (
            <FunctionRow key={`m${m.name}${m.line}`} fn={m} q={q} />
          ))}
          {(t.types || []).map((n) => (
            <TypeBlock
              key={`t${n.name}${n.line}`}
              t={n}
              q={q}
              swift={swift}
              depth={depth + 1}
              expanded={expanded}
              toggle={toggle}
              keyPrefix={key}
            />
          ))}
        </ul>
      )}
    </li>
  );
}

function FileBlock({ f, q, expanded, toggle }) {
  const swift = f.language === "swift";
  const open = q ? true : expanded.has(f.path);
  const name = f.path.split("/").slice(-1)[0];
  const dir = f.path.slice(0, f.path.length - name.length);
  const nT = (f.types || []).length;
  const nF = (f.functions || []).length;
  const nV = (f.variables || []).length;
  return (
    <li className="file">
      <button type="button" className="disclosure file-head" onClick={() => toggle(f.path)} aria-expanded={open}>
        <span className="chev">{open ? "▾" : "▸"}</span>
        <span className="dir">{dir}</span>
        <strong>{name}</strong>
        <span className="counts">
          {f.lines} lines · {nT} {swift ? "types" : "classes"} · {nF} fn · {nV} var
        </span>
      </button>
      {f.doc && <div className="doc">{f.doc}</div>}
      {open && (
        <ul className="symbols">
          {(f.types || []).map((t) => (
            <TypeBlock
              key={`t${t.name}${t.line}`}
              t={t}
              q={q}
              swift={swift}
              depth={0}
              expanded={expanded}
              toggle={toggle}
              keyPrefix={f.path}
            />
          ))}
          {(f.functions || []).map((fn) => (
            <FunctionRow key={`f${fn.name}${fn.line}`} fn={fn} q={q} />
          ))}
          {(f.variables || []).map((v) => (
            <VariableRow key={`v${v.name}${v.line}`} v={v} q={q} swift={swift} />
          ))}
          {!nT && !nF && !nV && <li className="muted">No top-level declarations.</li>}
        </ul>
      )}
    </li>
  );
}

// ------------------------------------------------------------------------------------------
// panels

function PackageChip({ id, byId, onSelect }) {
  const p = byId[id];
  return (
    <button type="button" className="chip" onClick={() => onSelect(id)}>
      {p ? p.name : id}
    </button>
  );
}

function EdgeDetails({ edge }) {
  const d = edge.details || [];
  if (edge.kind === "import") {
    return (
      <ul className="detail-list">
        {d.map((x) => (
          <li key={`${x.file}${x.line}${x.module}`}>
            <code>{x.file}</code>:{x.line} → <code>{x.module}</code>
          </li>
        ))}
      </ul>
    );
  }
  if (edge.kind === "reference") {
    return (
      <ul className="detail-list">
        {d.map((x) => (
          <li key={x.file}>
            <code>{x.file}</code> → {x.types.join(", ")}
          </li>
        ))}
      </ul>
    );
  }
  if (edge.kind === "http") {
    return (
      <ul className="detail-list">
        {d.map((x) => (
          <li key={`${x.method}${x.path}`}>
            <code>
              {x.method} {x.path}
            </code>{" "}
            → <code>{x.server_file}</code>
          </li>
        ))}
      </ul>
    );
  }
  return (
    <ul className="detail-list">
      {d.map((x) => (
        <li key={`${x.contract}${x.source_module}${x.forbidden_module}`}>
          <code>{x.source_module}</code> ⇸ <code>{x.forbidden_module}</code>{" "}
          <span className="muted">({x.contract})</span>
        </li>
      ))}
    </ul>
  );
}

function EdgePanel({ edge, byId, onSelect }) {
  return (
    <div>
      <h2>
        {KINDS[edge.kind].label}
        {edge.partial ? ` (${partialText(edge)})` : ""}
      </h2>
      <p>
        <PackageChip id={edge.source} byId={byId} onSelect={onSelect} /> →{" "}
        <PackageChip id={edge.target} byId={byId} onSelect={onSelect} />
        {edge.inferred && <span className="badge">inferred</span>}
      </p>
      {edge.violation && (
        <div className="alert">
          Violates a forbidden contract:
          <ul className="detail-list">
            {edge.violations.map((v) => (
              <li key={`${v.file}${v.line}${v.imported}`}>
                <code>{v.file}</code>:{v.line} imports <code>{v.imported}</code> ({v.contract})
              </li>
            ))}
          </ul>
        </div>
      )}
      <h3>Files</h3>
      <ul className="detail-list">
        {edge.files.length ? edge.files.map((f) => <li key={f}><code>{f}</code></li>) : <li className="muted">none (rule only)</li>}
      </ul>
      <h3>Details</h3>
      <EdgeDetails edge={edge} />
    </div>
  );
}

function Overview({ data, overlay, byId, onSelect, drift }) {
  const ovNotes = overlay.notes || [];
  const contractNames = (data.contracts || []).map((c) => c.name);
  const broken = new Set((data.violations || []).map((v) => v.contract));
  const issues = data.http_issues || {};
  return (
    <div>
      <h2>Overview</h2>
      <p className="muted">
        Click a package for its files and symbols, or an edge for the files that create it. Positions come from
        overlay.json; everything else is generated by <code>server/scripts/arch_extract.py</code>.
      </p>
      <h3>import-linter forbidden contracts</h3>
      <ul className="detail-list">
        {contractNames.map((n) => (
          <li key={n}>
            <span className={broken.has(n) ? "status bad" : "status ok"}>
              {broken.has(n) ? "direct violation" : "no direct violations"}
            </span>{" "}
            <code>{n}</code>
          </li>
        ))}
      </ul>
      <p className="muted small">
        The extractor checks direct imports only. <code>lint-imports</code> (run from <code>server/</code>) is
        authoritative, including indirect import chains.
      </p>
      {(data.violations || []).length > 0 && (
        <div className="alert">
          <strong>{data.violations.length} direct-import violation(s)</strong>
          <ul className="detail-list">
            {data.violations.map((v) => (
              <li key={`${v.file}${v.line}${v.imported}`}>
                <code>{v.file}</code>:{v.line} imports <code>{v.imported}</code> ({v.contract})
              </li>
            ))}
          </ul>
        </div>
      )}
      <h3>Contract ↔ code routes</h3>
      <ul className="detail-list">
        {Object.keys(issues)
          .sort()
          .map((k) => (
            <li key={k}>
              {k.replace(/_/g, " ")}: {issues[k].length ? issues[k].map((x) => <code key={x}>{x} </code>) : <span className="muted">none</span>}
            </li>
          ))}
      </ul>
      {(drift.missingOverlay.length > 0 || drift.staleOverlay.length > 0) && (
        <div className="alert">
          <strong>Overlay drift</strong>
          {drift.missingOverlay.length > 0 && <div>Not in overlay.json: {drift.missingOverlay.join(", ")}</div>}
          {drift.staleOverlay.length > 0 && <div>In overlay.json but not in code: {drift.staleOverlay.join(", ")}</div>}
        </div>
      )}
      <h3>Notes</h3>
      {ovNotes.map((n) => (
        <div key={n.title} className="note">
          <strong>{n.title}</strong>
          <p>{n.text}</p>
          <div>
            {(n.packages || []).map((id) => (
              <PackageChip key={id} id={id} byId={byId} onSelect={onSelect} />
            ))}
          </div>
        </div>
      ))}
      {(data.ambiguous_swift_types || []).length > 0 && (
        <p className="muted">Ambiguous Swift type names (not used for edges): {data.ambiguous_swift_types.join(", ")}</p>
      )}
    </div>
  );
}

function PackagePanel({ pkg, data, overlay, byId, onSelect, onSelectEdge }) {
  const [query, setQuery] = useState("");
  const [expanded, setExpanded] = useState(() => new Set());
  const toggle = useCallback(
    (k) =>
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(k)) next.delete(k);
        else next.add(k);
        return next;
      }),
    []
  );
  const ov = (overlay.packages || {})[pkg.id] || {};
  const layer = (overlay.layers || []).find((l) => l.id === ov.layer);
  const q = query.trim().toLowerCase();
  const files = pkg.files.map((f) => filterFile(f, q)).filter(Boolean);
  const out = data.edges.filter((e) => e.source === pkg.id && e.target !== pkg.id);
  const inc = data.edges.filter((e) => e.target === pkg.id && e.source !== pkg.id);
  const internal = data.edges.filter((e) => e.source === pkg.id && e.target === pkg.id);
  const routes = (data.routes || []).filter(
    (r) => r.server_package === pkg.id || (pkg.id === "ios:Core/Networking" && r.callers.length)
  );

  const edgeList = (list, dir) =>
    Object.keys(KINDS).map((kind) => {
      const es = list.filter((e) => e.kind === kind);
      if (!es.length) return null;
      return (
        <div key={kind} className="edge-group">
          <span className={`kind-tag k-${kind}`}>{kind}</span>
          {es.map((e) => (
            <button
              key={e.id}
              type="button"
              className={`chip ${e.violation ? "chip-bad" : ""}`}
              onClick={() => onSelectEdge(e.id)}
              title={`${e.files.length} file(s)`}
            >
              {byId[dir === "out" ? e.target : e.source]?.name || (dir === "out" ? e.target : e.source)}
              {e.partial ? "*" : ""}
            </button>
          ))}
        </div>
      );
    });

  return (
    <div>
      <h2>
        {pkg.name} <span className="muted small">{pkg.side} · {pkg.kind}{layer ? ` · ${layer.label}` : ""}</span>
      </h2>
      {pkg.path && (
        <p className="muted small">
          <code>{pkg.path}</code>
        </p>
      )}
      {ov.description ? <p>{ov.description}</p> : <p className="alert">No overlay description for {pkg.id}.</p>}
      {(ov.notes || []).map((n) => (
        <div key={n} className="note warn">
          {n}
        </div>
      ))}
      <h3>Depends on</h3>
      {out.length ? edgeList(out, "out") : <p className="muted">nothing</p>}
      <h3>Used by</h3>
      {inc.length ? edgeList(inc, "in") : <p className="muted">nothing</p>}
      {internal.length > 0 && (
        <>
          <h3>Internal rules</h3>
          {internal.map((e) => (
            <EdgeDetails key={e.id} edge={e} />
          ))}
        </>
      )}
      {routes.length > 0 && (
        <>
          <h3>{pkg.side === "ios" ? "Server routes called" : "Routes served"}</h3>
          <ul className="detail-list">
            {routes.map((r) => (
              <li key={`${r.method}${r.path}`}>
                <code>
                  {r.method} {r.path}
                </code>
                {!r.contract_path && <span className="badge bad">not in contract</span>}
                {pkg.side === "server" && !r.callers.length && <span className="badge">no iOS caller</span>}
                {pkg.side === "ios" && <span className="muted"> → {r.server_file}</span>}
              </li>
            ))}
          </ul>
        </>
      )}
      {pkg.files.length > 0 && (
        <>
          <h3>
            Files <span className="muted small">({pkg.files.length})</span>
          </h3>
          <input
            type="search"
            className="filter"
            placeholder="Filter symbols by name…"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            aria-label="Filter symbols by name"
          />
          <ul className="files">
            {files.map((f) => (
              <FileBlock key={f.path} f={f} q={q} expanded={expanded} toggle={toggle} />
            ))}
            {!files.length && <li className="muted">No symbol matches “{query}”.</li>}
          </ul>
        </>
      )}
    </div>
  );
}

// ------------------------------------------------------------------------------------------
// the map

function Tooltip({ hover, byId }) {
  if (!hover) return null;
  const e = hover.edge;
  const left = Math.max(8, Math.min(hover.x + 14, window.innerWidth - 400));
  const top = Math.max(8, Math.min(hover.y + 14, window.innerHeight - 260));
  const files = e.files.slice(0, 14);
  return (
    <div className="tooltip" style={{ left, top }} role="tooltip">
      <div className="tt-head">
        <span className={`kind-tag k-${e.kind}`}>{e.kind}</span> {byId[e.source]?.name} → {byId[e.target]?.name}
        {e.violation && <span className="badge bad">violation</span>}
        {e.partial && <span className="badge">{partialText(e)}</span>}
      </div>
      {files.length ? (
        <ul>
          {files.map((f) => (
            <li key={f}>{f}</li>
          ))}
          {e.files.length > files.length && <li>… {e.files.length - files.length} more</li>}
        </ul>
      ) : (
        <div className="muted">
          {e.details.length} rule(s); no file violates {e.details.length === 1 ? "it" : "them"}
        </div>
      )}
    </div>
  );
}

function ArchitectureMap({ data, overlay }) {
  const [selected, setSelected] = useState(null);
  const [selectedEdge, setSelectedEdge] = useState(null);
  const [hover, setHover] = useState(null);
  const [shown, setShown] = useState({ import: true, reference: true, http: true, forbidden: true });

  const byId = useMemo(() => Object.fromEntries(data.packages.map((p) => [p.id, p])), [data]);
  const layout = useMemo(() => computeLayout(data.packages, overlay), [data, overlay]);
  const drift = useMemo(() => {
    const ov = Object.keys(overlay.packages || {});
    return {
      missingOverlay: data.packages.map((p) => p.id).filter((id) => !ov.includes(id)),
      staleOverlay: ov.filter((id) => !byId[id]),
    };
  }, [data, overlay, byId]);
  const violators = useMemo(() => {
    const s = new Set();
    data.edges.filter((e) => e.violation && e.kind !== "forbidden").forEach((e) => s.add(e.source));
    return s;
  }, [data]);

  const drawn = data.edges.filter((e) => e.source !== e.target && shown[e.kind] && layout.pos[e.source] && layout.pos[e.target]);
  const focus = selected || null;
  const isLit = (e) => !focus || e.source === focus || e.target === focus || e.id === selectedEdge;
  const neighbours = useMemo(() => {
    if (!focus) return null;
    const s = new Set([focus]);
    drawn.forEach((e) => {
      if (e.source === focus) s.add(e.target);
      if (e.target === focus) s.add(e.source);
    });
    return s;
  }, [focus, drawn]);

  const selectPackage = (id) => {
    setSelected(id);
    setSelectedEdge(null);
  };
  const selectEdge = (id) => setSelectedEdge(id);

  const counts = {};
  data.edges.forEach((e) => {
    if (e.source !== e.target) counts[e.kind] = (counts[e.kind] || 0) + 1;
  });
  const sideCount = (side) => data.packages.filter((p) => p.side === side).length;
  const edgeObj = selectedEdge ? data.edges.find((e) => e.id === selectedEdge) : null;

  const strokeFor = (e) => (e.violation ? "var(--edge-violation)" : `var(--edge-${e.kind})`);
  const markerFor = (e) => `url(#arrow-${e.violation ? "violation" : e.kind})`;

  const ordered = [...drawn].sort((a, b) => Number(isLit(a)) - Number(isLit(b)) || Number(a.violation) - Number(b.violation));

  return (
    <div className="app">
      <header className="top">
        <div>
          <h1>ReclaimMyTime: architecture</h1>
          <p className="muted small">
            {sideCount("server")} server nodes · {sideCount("ios")} iOS packages ·{" "}
            {Object.keys(KINDS)
              .map((k) => `${counts[k] || 0} ${k}`)
              .join(" · ")}{" "}
            edges · {(data.violations || []).length} violations
          </p>
        </div>
        <div className="legend" role="group" aria-label="Edge kinds">
          {Object.entries(KINDS).map(([k, v]) => (
            <label key={k} className="legend-item">
              <input type="checkbox" checked={shown[k]} onChange={() => setShown({ ...shown, [k]: !shown[k] })} />
              <svg width="38" height="10" aria-hidden="true">
                <line
                  x1="1"
                  y1="5"
                  x2="37"
                  y2="5"
                  style={{ stroke: `var(--edge-${k})` }}
                  strokeWidth={v.width + 0.6}
                  strokeDasharray={v.dash || undefined}
                />
              </svg>
              {v.label}
            </label>
          ))}
          <span className="legend-item">
            <svg width="38" height="10" aria-hidden="true">
              <line x1="1" y1="5" x2="37" y2="5" style={{ stroke: "var(--edge-violation)" }} strokeWidth="3.2" />
            </svg>
            violating edge
          </span>
        </div>
      </header>
      <div className="layout">
        <div className="map-wrap">
          <svg
            className="map"
            viewBox={`0 0 ${VIEW_W} ${layout.height}`}
            role="img"
            aria-label="Package dependency map"
            onClick={() => selectPackage(null)}
          >
            <defs>
              {["import", "reference", "http", "forbidden", "violation"].map((k) => (
                <marker
                  key={k}
                  id={`arrow-${k}`}
                  viewBox="0 0 10 10"
                  refX="9"
                  refY="5"
                  markerWidth="7"
                  markerHeight="7"
                  orient="auto-start-reverse"
                >
                  <path d="M0,0 L10,5 L0,10 z" style={{ fill: `var(--edge-${k})` }} />
                </marker>
              ))}
            </defs>
            {Object.entries(REGIONS).map(([side, r]) => (
              <g key={side}>
                <text x={r.x + 6} y={24} className="region-title">
                  {r.title}
                </text>
                <text x={r.x + 6} y={44} className="region-sub">
                  {r.sub}
                </text>
              </g>
            ))}
            <line x1={DIVIDER_X} y1={8} x2={DIVIDER_X} y2={layout.height - 4} className="divider" />
            {layout.bands.map((b) => (
              <g key={`${b.side}${b.y}`}>
                <rect x={b.x + 2} y={b.y} width={b.w - 4} height={b.h} rx="8" className="band" />
              </g>
            ))}
            <g className="edges">
              {ordered.map((e) => {
                const k = KINDS[e.kind];
                const lit = isLit(e);
                const d = edgeGeometry(layout.pos[e.source], layout.pos[e.target], e.kind);
                const faint = e.kind === "forbidden" && e.partial && !e.violation;
                return (
                  <g
                    key={e.id}
                    className={`edge ${lit ? "lit" : "dim"} ${e.id === selectedEdge ? "picked" : ""}`}
                    onMouseMove={(ev) => setHover({ edge: e, x: ev.clientX, y: ev.clientY })}
                    onMouseLeave={() => setHover(null)}
                    onClick={(ev) => {
                      ev.stopPropagation();
                      selectEdge(e.id);
                    }}
                  >
                    <path d={d} className="edge-hit" />
                    <path
                      d={d}
                      fill="none"
                      style={{ stroke: strokeFor(e) }}
                      strokeWidth={e.violation ? 3.2 : faint ? k.width * 0.75 : k.width}
                      strokeDasharray={e.violation && e.kind !== "forbidden" ? undefined : k.dash || undefined}
                      opacity={faint ? 0.7 : 1}
                      markerEnd={markerFor(e)}
                      className={e.violation ? "violating" : undefined}
                    />
                  </g>
                );
              })}
            </g>
            <g className="band-labels" aria-hidden="true">
              {layout.bands.flatMap((b) =>
                b.labels.map((l) => (
                  <text key={`${b.side}${b.y}${l.text}`} x={l.x} y={b.y + 17} className="band-label">
                    {l.text}
                  </text>
                ))
              )}
            </g>
            <g className="nodes">
              {data.packages.map((p) => {
                const n = layout.pos[p.id];
                if (!n) return null;
                const dim = neighbours && !neighbours.has(p.id);
                const ext = p.kind === "external";
                const syms = countSymbols(p.files);
                return (
                  <g
                    key={p.id}
                    className={`node ${selected === p.id ? "selected" : ""} ${dim ? "dim" : ""} ${ext ? "external" : ""} ${
                      violators.has(p.id) ? "violator" : ""
                    }`}
                    transform={`translate(${n.x - n.w / 2},${n.y - n.h / 2})`}
                    tabIndex="0"
                    role="button"
                    aria-label={`${p.name} package`}
                    onClick={(ev) => {
                      ev.stopPropagation();
                      selectPackage(p.id);
                    }}
                    onKeyDown={(ev) => {
                      if (ev.key === "Enter" || ev.key === " ") {
                        ev.preventDefault();
                        selectPackage(p.id);
                      }
                    }}
                  >
                    <title>{((overlay.packages || {})[p.id] || {}).description || p.id}</title>
                    <rect width={n.w} height={n.h} rx="7" className="node-box" />
                    <rect width="5" height={n.h} rx="2" style={{ fill: n.color }} />
                    <text x="14" y="22" className="node-name">
                      {p.name.split("/").pop()}
                    </text>
                    <text x="14" y="41" className="node-meta">
                      {ext ? "external · forbidden target" : `${plural(p.files.length, "file")} · ${plural(syms, "symbol")}`}
                    </text>
                  </g>
                );
              })}
            </g>
          </svg>
        </div>
        <aside className="panel" aria-live="polite">
          {edgeObj ? (
            <>
              <button type="button" className="back" onClick={() => setSelectedEdge(null)}>
                ← {selected ? byId[selected]?.name : "overview"}
              </button>
              <EdgePanel edge={edgeObj} byId={byId} onSelect={selectPackage} />
            </>
          ) : selected && byId[selected] ? (
            <>
              <button type="button" className="back" onClick={() => selectPackage(null)}>
                ← overview
              </button>
              <PackagePanel
                key={selected}
                pkg={byId[selected]}
                data={data}
                overlay={overlay}
                byId={byId}
                onSelect={selectPackage}
                onSelectEdge={selectEdge}
              />
            </>
          ) : (
            <Overview data={data} overlay={overlay} byId={byId} onSelect={selectPackage} drift={drift} />
          )}
        </aside>
      </div>
      <Tooltip hover={hover} byId={byId} />
    </div>
  );
}

window.ArchitectureMap = ArchitectureMap;
